CREATE TABLE IF NOT EXISTS migrations (version INT PRIMARY KEY, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admins (id INT AUTO_INCREMENT PRIMARY KEY, login VARCHAR(40) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, secret TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT 1, last_totp BIGINT NOT NULL DEFAULT 0, failures INT NOT NULL DEFAULT 0, locked_until BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS materials (id INT AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(10) NOT NULL, draft JSON NOT NULL, published JSON NULL, sort_order INT NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS revisions (id INT AUTO_INCREMENT PRIMARY KEY, material_id INT NOT NULL, payload JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit (id INT AUTO_INCREMENT PRIMARY KEY, admin_id INT NULL, action VARCHAR(80) NOT NULL, material_id INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS images (id CHAR(32) PRIMARY KEY, path VARCHAR(100) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS previews (token CHAR(64) PRIMARY KEY, payload JSON NOT NULL, expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS login_throttle (bucket CHAR(64) PRIMARY KEY, attempts INT NOT NULL DEFAULT 0, expires BIGINT NOT NULL);
